public class Account
{
 public int Balance {get;private set;}
 public Account(int balance)
 {if(balance<0)throw new ArgumentOutOfRangeException(nameof(balance));Balance=balance;}
 public bool Deposit(int amount)
 {if(amount<=0)return false;Balance=checked(Balance+amount);return true;}
}

