using Xunit;
public class AccountTests {
 [Theory][InlineData(0,false)][InlineData(5,true)] public void Deposit(int amount,bool accepted){var a=new Account(0);Assert.Equal(accepted,a.Deposit(amount));Assert.Equal(accepted?amount:0,a.Balance);}
 [Fact] public void RejectsNegative()=>Assert.Throws<ArgumentOutOfRangeException>(()=>new Account(-1));
 [Fact] public async Task DependencyFailure(){Func<Task> source=()=>Task.FromException(new InvalidOperationException("offline"));await Assert.ThrowsAsync<InvalidOperationException>(source);}
}
